import sys

def solve():
    t_str = sys.stdin.readline()
    if not t_str:
        return
    t = int(t_str)

    for _ in range(t):
        line = sys.stdin.readline()
        while line and not line.strip():
            line = sys.stdin.readline()
        if not line:
            break

        parts = list(map(int, line.split()))
        n = parts[0]
        k = parts[1]

        low = 0
        high = n - 1

        while low < high:
            mid = (low + high) // 2
            print(mid)
            sys.stdout.flush()

            res = int(sys.stdin.readline())
            if res == -1:
                return
            if res == 1:
                break
            else:
                if mid >= n:
                    high = mid - 1
                else:
                    low = mid + 1
        else:
            print(low)
            sys.stdout.flush()
